// Configuration of the OPSYS context engine (OPSYS-AI PLAN T3.3-suite, ADR-0010 decisions 3 and 4).
//
// Read from `<config dir>/opsys/contexte.json`, next to `metier.json` and `roles.json`
// (`src/gateway/opsys-metier-config.ts`, `src/gateway/opsys-device-roles.ts`). Like them it is
// deliberately NOT part of the Zod-validated `OpenClawConfig`: the root schema is strict, and adding
// a key would also move the generated config baseline of an upstream surface OPSYS does not own.
// The file is GENERATED by `src/opsys/openclaw.py` (`opsys metier openclaw configurer
// --contexte-entreprise ...`); the same command selects this engine in `plugins.slots.contextEngine`.
//
// OFF by default: a missing file, or a file without `"actif": true`, changes nothing to any agent
// turn. Fail-closed once enabled: a malformed value is reported as `invalid` and the engine says so
// in the turn's context (see `opsys-contexte-engine.ts`); it is never replaced by an invented default.
//
// File format (keys are French like the other OPSYS fragments):
//   {
//     "actif": true,                                   // required, must be exactly true
//     "serveur": "opsys_m10",                          // key of the M10 server in `mcp.servers`
//     "outil_paquet": "m10_paquet_contexte_affaire",   // read tool (T0), PREFLIGHT
//     "outil_depot": "m10_deposer_faits_candidats",    // deposit tool, POSTFLIGHT
//     "outil_affaire": "m10_affaire_de_la_session",    // read tool (T0), case of a session
//     "delai_ms": 4000,                                // bound of ONE call to the engine
//     "version": 2,                                      // generated format; older active fragments must be regenerated
//     "niveaux": { "m3_estimer_projet": "N3", ... },   // level N0..N5 of every OPSYS tool
//     "cibles": {
//       "m3_estimer_projet": {"type":"affaire", "chemin":["contrat","lead_id"], "identite":"lead"},
//       "m2_transitionner_statut": {"type":"ticket"}, // only the eight Python-declared target mutations
//       "m2_unknown_tool": {"type":"inconnue"}        // remains blocked at N3+
//     },
//     "agents": {                                      // required, non-empty
//       "m03-estimation": { "depot": ["m3_estimer_projet"], "serveur_contexte": "opsys_context_m03-estimation" },
//       "m01-front-office": { "affaire": "session", "serveur_contexte": "opsys_context_m01-front-office" }
//     }
//   }
// `agents` names the agents that get the packet before their turn; `depot` lists the department
// tools whose results are handed to M10 after the turn (empty or absent: nothing is deposited).
// `affaire` says where the case of a turn comes from: "demande" (default) reads the line
// `affaire_id: <lead_id>` of the request, acceptable ONLY for an agent that receives internal
// requests; "session" asks M10 for the case linked to the SESSION KEY (`outil_affaire`), and never
// reads the text of the request, which on a client channel is the client's.
// `niveaux` is generated by `openclaw.py` from the manifests (`Outil.niveau_effectif`), never taken
// from the model: it is what the `before_tool_call` guard (`opsys-contexte-garde.ts`) reads to know
// which tool calls need a usable context (N3 or more).
import fs from "node:fs";
import path from "node:path";
import { isValidAgentId, normalizeAgentId } from "@openclaw/normalization-core/agent-id";
import { asSafeIntegerInRange } from "@openclaw/normalization-core/number-coercion";
import { isRecord } from "@openclaw/normalization-core/record-coerce";
import { resolveOpsysDir } from "../gateway/opsys-metier-config.js";
import { formatErrorMessage } from "../infra/errors.js";
import { isOpsysCibleTicketTool } from "./opsys-contexte-cibles.js";

export const OPSYS_CONTEXTE_CONFIG_FILENAME = "contexte.json";

const DEFAULT_SERVER = "opsys_m10";
const DEFAULT_PACKET_TOOL = "m10_paquet_contexte_affaire";
const DEFAULT_DEPOSIT_TOOL = "m10_deposer_faits_candidats";
const DEFAULT_AFFAIRE_TOOL = "m10_affaire_de_la_session";
const DEPARTMENT_ORIGIN_PATTERN = /^m(0[1-9]|10)-[a-z][a-z0-9-]+$/;
const DEFAULT_TIMEOUT_MS = 4_000;
const TIMEOUT_RANGE = { min: 100, max: 30_000 };
const SERVER_PATTERN = /^[A-Za-z0-9_-]{1,64}$/u;
const TOOL_PATTERN = /^m(?:10|[1-9])_[a-z][a-z0-9_]{1,60}$/u;

/** Approval level of an OPSYS tool (ADR-0009 §4), as generated by OPSYS from the manifests. */
export type OpsysToolLevel = "N0" | "N1" | "N2" | "N3" | "N4" | "N5";

export const OPSYS_TOOL_LEVELS: readonly OpsysToolLevel[] = ["N0", "N1", "N2", "N3", "N4", "N5"];
const MIN_GUARDED_RANK = OPSYS_TOOL_LEVELS.indexOf("N3");

export type OpsysContexteConfig = Readonly<{
  /** Key of the M10 server in `mcp.servers` (its URL and token header are the existing ones). */
  server: string;
  packetTool: string;
  depositTool: string;
  /** Read tool that gives the case linked to a session key (agents whose case comes from the session). */
  affaireTool: string;
  /** Bound of ONE call to the engine: the turn never waits longer for it. */
  timeoutMs: number;
  /** Agent id -> department tools whose results are deposited after the turn. */
  agents: ReadonlyMap<string, readonly string[]>;
  /** Agents whose case comes from the session key, never from the text of the request. */
  affaireFromSession: ReadonlySet<string>;
  /** Origin-bound M10 packet server per agent, configured by the generator. */
  contextServers: ReadonlyMap<string, string>;
  /** Session agent -> canonical department origin of its filtered packet. Legacy configs use self. */
  packetOrigins?: ReadonlyMap<string, string>;
  /** Bare OPSYS tool name -> its level N, generated by OPSYS (never by the model). */
  levels: ReadonlyMap<string, OpsysToolLevel>;
  /** Bare N3+ tool -> explicit case/global scope; unknown means block until its owner declares one. */
  targets: ReadonlyMap<string, OpsysToolTarget>;
}>;

export type OpsysToolTarget =
  | { kind: "unknown" }
  | { kind: "global" }
  /** Only the exact ticketed mutation set; Python resolves the final target before any effect. */
  | { kind: "ticket" }
  | { kind: "affaire"; path: readonly string[]; identity: "affaire" | "lead" | "wct" };

export type OpsysContexteConfigResult =
  /** No `contexte.json`: the engine is transparent. */
  | { kind: "absent" }
  /** The file exists without `"actif": true`: the engine is transparent. */
  | { kind: "disabled" }
  /** The operator asked for the engine but the file cannot be trusted. */
  | { kind: "invalid"; reason: string }
  | { kind: "enabled"; config: OpsysContexteConfig };

function invalid(reason: string): OpsysContexteConfigResult {
  return { kind: "invalid", reason };
}

function readName(
  root: Record<string, unknown>,
  key: string,
  fallback: string,
  pattern: RegExp,
): string | undefined {
  const raw = root[key];
  if (raw === undefined) {
    return fallback;
  }
  return typeof raw === "string" && pattern.test(raw) ? raw : undefined;
}

function parseAgents(
  raw: unknown,
  requireContextServer: boolean,
):
  | {
      ok: true;
      agents: Map<string, readonly string[]>;
      fromSession: Set<string>;
      contextServers: Map<string, string>;
      packetOrigins: Map<string, string>;
    }
  | { ok: false; reason: string } {
  if (!isRecord(raw) || Object.keys(raw).length === 0) {
    return { ok: false, reason: '"agents" must map at least one agent id to its settings' };
  }
  const agents = new Map<string, readonly string[]>();
  const fromSession = new Set<string>();
  const contextServers = new Map<string, string>();
  const packetOrigins = new Map<string, string>();
  for (const [rawId, settings] of Object.entries(raw)) {
    if (!isValidAgentId(rawId)) {
      return { ok: false, reason: `"agents" has an invalid agent id: ${JSON.stringify(rawId)}` };
    }
    const agentId = normalizeAgentId(rawId);
    if (agents.has(agentId)) {
      return { ok: false, reason: `"agents" lists ${JSON.stringify(agentId)} twice` };
    }
    if (!isRecord(settings)) {
      return { ok: false, reason: `"agents.${agentId}" must be an object` };
    }
    const deposit: unknown = settings.depot === undefined ? [] : settings.depot;
    if (
      !Array.isArray(deposit) ||
      !deposit.every((tool): tool is string => typeof tool === "string" && TOOL_PATTERN.test(tool))
    ) {
      return {
        ok: false,
        reason: `"agents.${agentId}.depot" must list department tool names such as m3_estimer_projet`,
      };
    }
    const affaire: unknown = settings.affaire === undefined ? "demande" : settings.affaire;
    if (affaire !== "demande" && affaire !== "session") {
      return { ok: false, reason: `"agents.${agentId}.affaire" must be "demande" or "session"` };
    }
    if (affaire === "session") {
      fromSession.add(agentId);
    }
    const contextServer = settings.serveur_contexte;
    if (
      requireContextServer &&
      (typeof contextServer !== "string" || !SERVER_PATTERN.test(contextServer))
    ) {
      return {
        ok: false,
        reason: `"agents.${agentId}.serveur_contexte" must name its origin-bound M10 server (regenerate with \`opsys metier openclaw configurer\`)`,
      };
    }
    if (typeof contextServer === "string" && SERVER_PATTERN.test(contextServer)) {
      contextServers.set(agentId, contextServer);
    }
    // Old mixed v2 files stay usable for standards. An unbound profile keeps its exact alias,
    // so a department packet remains rejected until the host regenerates an explicit binding.
    let packetOrigin = agentId;
    if (Object.hasOwn(settings, "origine_paquet")) {
      const origin = settings.origine_paquet;
      if (
        typeof origin !== "string" ||
        !DEPARTMENT_ORIGIN_PATTERN.test(origin) ||
        contextServer !== `opsys_context_${origin}` ||
        (DEPARTMENT_ORIGIN_PATTERN.test(agentId) && origin !== agentId)
      ) {
        return {
          ok: false,
          reason: `"agents.${agentId}.origine_paquet" must bind its canonical department and context server`,
        };
      }
      packetOrigin = origin;
    }
    packetOrigins.set(agentId, packetOrigin);
    agents.set(agentId, [...new Set(deposit)]);
  }
  return { ok: true, agents, fromSession, contextServers, packetOrigins };
}

function isToolLevel(value: unknown): value is OpsysToolLevel {
  return typeof value === "string" && (OPSYS_TOOL_LEVELS as readonly string[]).includes(value);
}

function parseLevels(
  raw: unknown,
): { ok: true; levels: Map<string, OpsysToolLevel> } | { ok: false; reason: string } {
  const reason =
    '"niveaux" must map OPSYS tool names to a level N0..N5 (regenerate the file with `opsys metier openclaw configurer`)';
  if (!isRecord(raw) || Object.keys(raw).length === 0) {
    return { ok: false, reason };
  }
  const levels = new Map<string, OpsysToolLevel>();
  for (const [tool, level] of Object.entries(raw)) {
    if (!TOOL_PATTERN.test(tool) || !isToolLevel(level)) {
      return { ok: false, reason: `${reason}; bad entry ${JSON.stringify(tool)}` };
    }
    levels.set(tool, level);
  }
  return { ok: true, levels };
}

function parseTargets(
  raw: unknown,
  levels: ReadonlyMap<string, OpsysToolLevel>,
): { ok: true; targets: Map<string, OpsysToolTarget> } | { ok: false; reason: string } {
  if (!isRecord(raw)) {
    return {
      ok: false,
      reason:
        '"cibles" must be generated for active contexts; regenerate with `opsys metier openclaw configurer`',
    };
  }
  const targets = new Map<string, OpsysToolTarget>();
  for (const [toolName, level] of levels) {
    if (OPSYS_TOOL_LEVELS.indexOf(level) < MIN_GUARDED_RANK) {
      continue;
    }
    const rawTarget = raw[toolName];
    if (!isRecord(rawTarget)) {
      return {
        ok: false,
        reason: `"cibles.${toolName}" is missing; regenerate with opsys metier openclaw configurer`,
      };
    }
    if (rawTarget.type === "inconnue") {
      targets.set(toolName, { kind: "unknown" });
      continue;
    }
    if (rawTarget.type === "ticket") {
      if (!isOpsysCibleTicketTool(toolName)) {
        return {
          ok: false,
          reason: `"cibles.${toolName}" cannot use the ticket target contract`,
        };
      }
      targets.set(toolName, { kind: "ticket" });
      continue;
    }
    if (rawTarget.type === "globale") {
      targets.set(toolName, { kind: "global" });
      continue;
    }
    if (
      rawTarget.type !== "affaire" ||
      !Array.isArray(rawTarget.chemin) ||
      rawTarget.chemin.length === 0 ||
      !rawTarget.chemin.every(
        (segment): segment is string => typeof segment === "string" && segment.length > 0,
      ) ||
      (rawTarget.identite !== "affaire" &&
        rawTarget.identite !== "lead" &&
        rawTarget.identite !== "wct")
    ) {
      return {
        ok: false,
        reason: `"cibles.${toolName}" has an invalid target binding; regenerate with opsys metier openclaw configurer`,
      };
    }
    targets.set(toolName, {
      kind: "affaire",
      path: [...rawTarget.chemin],
      identity: rawTarget.identite,
    });
  }
  for (const toolName of Object.keys(raw)) {
    const level = levels.get(toolName);
    if (level === undefined || OPSYS_TOOL_LEVELS.indexOf(level) < MIN_GUARDED_RANK) {
      return {
        ok: false,
        reason: `"cibles" contains an unguarded tool ${JSON.stringify(toolName)}`,
      };
    }
  }
  return { ok: true, targets };
}

/** Validates the parsed JSON of `contexte.json`. Exported for tests. */
export function parseOpsysContexteConfig(raw: unknown): OpsysContexteConfigResult {
  if (!isRecord(raw)) {
    return invalid("contexte.json must contain a JSON object");
  }
  if (raw.actif !== true) {
    return { kind: "disabled" };
  }
  const server = readName(raw, "serveur", DEFAULT_SERVER, SERVER_PATTERN);
  if (server === undefined) {
    return invalid('"serveur" must be the name of an entry of mcp.servers');
  }
  const packetTool = readName(raw, "outil_paquet", DEFAULT_PACKET_TOOL, TOOL_PATTERN);
  if (packetTool === undefined) {
    return invalid(
      '"outil_paquet" must be a department tool name such as m10_paquet_contexte_affaire',
    );
  }
  const depositTool = readName(raw, "outil_depot", DEFAULT_DEPOSIT_TOOL, TOOL_PATTERN);
  if (depositTool === undefined) {
    return invalid(
      '"outil_depot" must be a department tool name such as m10_deposer_faits_candidats',
    );
  }
  const affaireTool = readName(raw, "outil_affaire", DEFAULT_AFFAIRE_TOOL, TOOL_PATTERN);
  if (affaireTool === undefined) {
    return invalid(
      '"outil_affaire" must be a department tool name such as m10_affaire_de_la_session',
    );
  }
  const timeoutMs =
    raw.delai_ms === undefined
      ? DEFAULT_TIMEOUT_MS
      : asSafeIntegerInRange(raw.delai_ms, TIMEOUT_RANGE);
  if (timeoutMs === undefined) {
    return invalid(
      `"delai_ms" must be an integer from ${String(TIMEOUT_RANGE.min)} to ${String(TIMEOUT_RANGE.max)}`,
    );
  }
  const agents = parseAgents(raw.agents, raw.version === 2);
  if (!agents.ok) {
    return invalid(agents.reason);
  }
  const levels = parseLevels(raw.niveaux);
  if (!levels.ok) {
    return invalid(levels.reason);
  }
  if (raw.version !== 2) {
    return invalid(
      "configuration de contexte active obsolète ou non versionnée; régénérer avec `opsys metier openclaw configurer`",
    );
  }
  const targets = parseTargets(raw.cibles, levels.levels);
  if (!targets.ok) {
    return invalid(targets.reason);
  }
  return {
    kind: "enabled",
    config: {
      server,
      packetTool,
      depositTool,
      affaireTool,
      timeoutMs,
      agents: agents.agents,
      affaireFromSession: agents.fromSession,
      contextServers: agents.contextServers,
      packetOrigins: agents.packetOrigins,
      levels: levels.levels,
      targets: targets.targets,
    },
  };
}

/**
 * Reads `<opsys dir>/contexte.json`. `dir` overrides the default lookup (tests only; production
 * omits it). The read is synchronous and tiny: it runs once per engine resolution.
 */
export function readOpsysContexteConfig(
  params: { dir?: string; env?: NodeJS.ProcessEnv } = {},
): OpsysContexteConfigResult {
  const file = path.join(params.dir ?? resolveOpsysDir(params.env), OPSYS_CONTEXTE_CONFIG_FILENAME);
  let text: string;
  try {
    text = fs.readFileSync(file, "utf8");
  } catch (error) {
    if (error instanceof Error && "code" in error && error.code === "ENOENT") {
      return { kind: "absent" };
    }
    return invalid(`cannot read ${file}: ${formatErrorMessage(error)}`);
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(text);
  } catch (error) {
    return invalid(`${file} is not valid JSON: ${formatErrorMessage(error)}`);
  }
  return parseOpsysContexteConfig(parsed);
}
